// #e946b4 (6a993d72c6f011ffb0e946b4) «פיתוח: נתיב פנייה לגורם אנושי ובקשת התאמה» — проверено 04.11.2026, «עבר QA» 04.11.
//  - AC1: ссылка к человеку («?», имя «…פנייה לגורם אנושי») на экранах кандидата до звонка;
//  - AC5: сбой отправки (candidate_submit_support_request оборван) → «השליחה לא הצליחה. הטקסט שכתבתם נשמר», альтернативные
//    контакты (телефон tel:, e-mail mailto:), введённый текст остался в поле (скрин e946b4-send-fail-390.png);
//  - AC3: закрытие листа возвращает на тот же экран без потери прогресса (лист согласия с отмеченной галочкой).
//    Сохранение прокрутки не автоматизировано: у verifier 04.11 потеря прокрутки была артефактом Playwright.
// НЕ prod-safe: каждый тест создаёт кандидата «QA-AUTO-e946b4-…» (business, link_only), не удаляется → @data.
// Обращение реально НЕ отправляется (запрос оборван), звонок не начинается (blockCallStarts).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts } from './support';
import { A11Y, newCandidateLink, tapBtn } from './a11y-support';
import { HELP, TECH, closeHelp, helpEntry, helpSheet, openHelp, openWelcome, toConsent } from './help-1104-support';

const HASH = '#e946b4 · #6a993d72c6f011ffb0e946b4';

test.describe(`Кандидат — путь к человеку: ссылка, сбой отправки, возврат на экран (${HASH})`, () => {
  test(`«?» (…פנייה לגורם אנושי) на ברוכים הבאים, איך זה עובד, פרטי הלקוח, листе «לפני שמתחילים» и тех. проверке; открывает «${HELP.title}» @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-e946b4-L-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не начата), не удаляется` });
    const blocked = await blockCallStarts(page);

    // Источник: AC1 «בכל אחד ממסכי המועמד… מוצג הקישור לפנייה לגורם אנושי».
    await openWelcome(page, link);
    const screens: { id: string; next?: string | RegExp }[] = [
      { id: 'ברוכים הבאים', next: A11Y.welcomeCta },
      { id: 'איך זה עובד', next: A11Y.howCta },
      { id: 'פרטי הלקוח', next: A11Y.clientCta },
    ];
    for (const s of screens) {
      await expect(helpEntry(page), `«?» на «${s.id}»`).toBeVisible();
      await expect(helpEntry(page)).toHaveAccessibleName(A11Y.help);
      await tapBtn(page, s.next!);
    }
    await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
    await expect(helpEntry(page), '«?» на листе согласия').toBeVisible();
    await openHelp(page);
    await closeHelp(page);

    await page.getByRole('checkbox').first().check();
    await tapBtn(page, A11Y.consentCta);
    await expect(page.getByRole('button', { name: TECH.start })).toBeVisible({ timeout: 30_000 });
    await expect(helpEntry(page), '«?» на тех. проверке').toBeVisible();
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`сбой отправки (candidate_submit_support_request оборван) → «${HELP.sendFail}», телефон и e-mail для прямой связи, текст в поле сохранён, «${HELP.sent}» нет @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const stamp = runStamp();
    const name = `QA-AUTO-e946b4-S-${stamp}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (экран «פרטי הלקוח»), обращение НЕ отправлено, не удаляется` });
    const blocked = await blockCallStarts(page);
    let attempts = 0;
    await page.route('**/rest/v1/rpc/candidate_submit_support_request', (r) => {
      attempts++;
      return r.abort('failed');
    });

    await openWelcome(page, link);
    await tapBtn(page, A11Y.welcomeCta);
    await tapBtn(page, A11Y.howCta);
    await expect(page.getByRole('button', { name: A11Y.clientCta })).toBeVisible();
    await openHelp(page);

    const text = `QA-AUTO-e946b4-${stamp} בדיקת QA — לא לטפל`;
    await page.getByRole('radio', { name: 'תקלה טכנית' }).check();
    const field = page.getByRole('textbox', { name: HELP.description });
    await field.fill(text);
    await helpSheet(page).getByRole('button', { name: HELP.send, exact: true }).click();

    // Источник: AC5 «כשהשליחה נכשלה… מוצגים פרטי קשר חלופיים והטקסט שהזנתי נשמר».
    await expect(page.getByText(HELP.sendFail)).toBeVisible({ timeout: 30_000 });
    expect(attempts, 'запрос отправки не уходил').toBeGreaterThan(0);
    await expect(field).toHaveValue(text);
    await expect(page.getByRole('radio', { name: 'תקלה טכנית' })).toBeChecked();
    const sheet = helpSheet(page);
    await expect(sheet.locator('a[href^="tel:"]').first()).toBeVisible();
    await expect(sheet.locator('a[href^="mailto:"]').first()).toBeVisible();
    await expect(page.getByText(HELP.sent, { exact: true })).toHaveCount(0);
    await expect(sheet.getByRole('button', { name: HELP.send, exact: true })).toBeVisible(); // можно отправить ещё раз

    await closeHelp(page);
    await expect(page.getByRole('button', { name: A11Y.clientCta })).toBeVisible(); // тот же экран «פרטי הלקוח»
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`закрытие листа помощи («${HELP.close}») возвращает на тот же экран: лист «לפני שמתחילים» с отмеченной галочкой @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-e946b4-C-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (лист согласия, согласие не отправлено), не удаляется` });
    const blocked = await blockCallStarts(page);

    await toConsent(page, link);
    const consent = page.getByRole('checkbox').first();
    await consent.check();
    await openHelp(page);
    await closeHelp(page);

    // Источник: AC3 «כאשר אני סוגר את החלון, אז אני חוזר בדיוק לנקודה שבה הייתי ולא מאבד את התקדמותי».
    await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
    await expect(consent).toBeChecked();
    await expect(page.getByRole('button', { name: A11Y.consentCta })).toBeEnabled();
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
